      if(is('THU_02'))sigil(ctx,830,371,184,'THU',env(t,.10,.25,.43)*.58,t);
      if(is('THU_05'))sigil(ctx,820,379,220,'THU',env(t,.08,.27,.56),t);
      if(is('COM_02'))sigil(ctx,p.x,p.y,73,'BOW',env(t,.12,.28,.9)*.65,t);
